// Sinced: one-page landing for adityakolte.com/sinced, as a Framer code component.
// Paste into Framer (Assets → Code), place it on the page with Width: Fill, Height: Fit,
// then upload the screenshots and the four Allo font files in the right panel.
// The card patterns at the bottom of this file are generated by build-patterns.mjs.

import * as React from "react"
import { addPropertyControls, ControlType } from "framer"

const APP_STORE_URL =
    "https://apps.apple.com/in/app/sinced-days-since-counter/id6799975298"
const SITE_URL = "https://adityakolte.com/sinced"
const PRIVACY_URL = "https://adityakolte.com/sinced/privacy"
const SUPPORT_URL = "https://adityakolte.com/sinced/support"

type Img = { src?: string; alt?: string } | string | undefined
type Pattern = keyof typeof PATTERNS

interface Props {
    icon?: Img
    hero?: Img
    widgets?: Img
    runs?: Img
    reminders?: Img
    share?: Img
    anywhere?: Img
    alloRegular?: string
    alloMedium?: string
    alloSemiBold?: string
    alloBold?: string
    email: string
    stickyNav: boolean
    style?: React.CSSProperties
}

// ─── Content ────────────────────────────────────────────────────────────────

